import{_ as s,C as a,o as d,c,j as e,a as l,E as r,a6 as o}from"./chunks/framework.CD0vXS2f.js";const v=JSON.parse('{"title":"02 · Microsoft Fabric, OneLake & Fabric IQ Integration","description":"Integrating Microsoft Fabric, OneLake zero-copy shortcuts, Fabric IQ / Fabric Data Agents, Azure AI Search OneLake indexers, and F-SKU capacity isolation with Microsoft Foundry.","frontmatter":{"title":"02 · Microsoft Fabric, OneLake & Fabric IQ Integration","description":"Integrating Microsoft Fabric, OneLake zero-copy shortcuts, Fabric IQ / Fabric Data Agents, Azure AI Search OneLake indexers, and F-SKU capacity isolation with Microsoft Foundry."},"headers":[],"relativePath":"playbooks/ai-data-strategy/02-fabric-onelake-fabric-iq.md","filePath":"playbooks/ai-data-strategy/02-fabric-onelake-fabric-iq.md","lastUpdated":1795642852816,"verifiedStamp":"2026-11-25 13:40 PST"}'),g={name:"playbooks/ai-data-strategy/02-fabric-onelake-fabric-iq.md"};function u(h,t,f,p,y,b){const i=a("PlaybookMeta"),n=a("PageBrief");return d(),c("div",null,[t[0]||(t[0]=e("h1",{id:"_02-·-microsoft-fabric-onelake-fabric-iq-integration",tabindex:"-1"},[l("02 · Microsoft Fabric, OneLake & Fabric IQ Integration "),e("a",{class:"header-anchor",href:"#_02-·-microsoft-fabric-onelake-fabric-iq-integration","aria-label":'Permalink to "02 · Microsoft Fabric, OneLake & Fabric IQ Integration"'},"​")],-1)),r(i,{track:"05 · AI Data Strategy, Fabric–Foundry & Governance",verified:"2026-11-23 19:30 PST",status:"Live v2.0",studioHref:"/studio/#data-strategy",studioLabel:"Data Strategy Advisor →"}),r(n,{stage:"design",readTime:"6 min read",problem:"Connecting Microsoft Foundry agents directly to raw Bronze lakes or copying tabular ERP data into vector indexes causes hallucinated KPI math, duplicate storage sprawl, and F-SKU capacity throttling.",takeaway:"Adopt OneLake zero-copy Shortcuts into a Medallion AI-Ready Gold layer, route structured/analytical questions through Fabric IQ (Ontology + Semantic Models + Fabric Data Agents), index unstructured OneLake Files via Shared Private Link, and separate interactive AI F-SKU capacities from batch ETL.",csaUse:"Use the dual-path grounding diagram and F-SKU isolation checklist below during joint Data Platform + AI Architecture workshops."}),t[1]||(t[1]=o('<h2 id="_1-medallion-architecture-extended-to-ai-ready-gold-arch" tabindex="-1">1. Medallion Architecture Extended to <code>AI-Ready Gold</code> <code>[Arch]</code> <a class="header-anchor" href="#_1-medallion-architecture-extended-to-ai-ready-gold-arch" aria-label="Permalink to &quot;1. Medallion Architecture Extended to `AI-Ready Gold` `[Arch]`&quot;">​</a></h2><p>Enterprise data estates already standardize on <strong>Microsoft Fabric</strong> and <strong>OneLake</strong> (<code>Bronze → Silver → Gold</code>). Making that estate AI-ready does <strong>not</strong> require building a parallel shadow data lake. Instead, extend the Gold layer with an explicit <strong><code>AI-Ready Gold</code></strong> contract <span class="ev-badge ev-arch">[Arch]</span>:</p><ul><li><strong>Bronze (Raw Landing / Zero-Copy Shortcuts):</strong> Reference producer domains in ADLS Gen2, Amazon S3, Google Cloud Storage, Dataverse, or cross-workspace Fabric Lakehouses using <strong>OneLake Shortcuts</strong> rather than duplicating raw bytes <span class="ev-badge ev-m">[M]</span>.</li><li><strong>Silver (Conformed &amp; Governed):</strong> Deduplicate entities, apply <strong>Microsoft Purview sensitivity labels</strong> and domain ownership, strip PII columns where unnecessary, and validate schema contracts.</li><li><strong>Gold (Curated Business Truth):</strong> Publish governed Delta Parquet tables, Warehouses, and <strong>Power BI Semantic Models</strong> with certified DAX measures (revenue, margin, exposure, SLA compliance) so every BI dashboard and AI agent shares one mathematical definition <span class="ev-badge ev-m">[M]</span>.</li><li><strong>AI-Ready Gold (Dual Serving Surface):</strong><ol><li><strong>Structured &amp; Semantic Surface (<code>Fabric IQ</code>):</strong> Bind curated Lakehouse tables, Warehouses, Semantic Models, and Eventhouses to <strong>Fabric IQ</strong> ontologies and <strong>Fabric Data Agents</strong>, consumed directly by <strong>Microsoft Foundry Agent Service</strong> as a grounded tool <span class="ev-badge ev-m">[M]</span>.</li><li><strong>Unstructured Document Surface (<code>OneLake Files → Content Understanding → Azure AI Search</code>):</strong> Store layout-faithful Markdown and chunk metadata alongside lineage hashes (<code>source_uri</code>, <code>lineage_sha256</code>, <code>sensitivity_label</code>, <code>acl_group_ids</code>) and index via <strong>Azure AI Search OneLake Indexer</strong> over a <strong>Shared Private Link</strong> when workspace-level Private Link is enabled <span class="ev-badge ev-m">[M]</span>.</li></ol></li></ul>',3)),t[2]||(t[2]=e("div",{class:"arch-diagram"},[e("svg",{viewBox:"0 0 760 208",role:"img","aria-labelledby":"pb5-t2-title pb5-t2-desc","font-family":"Segoe UI, Inter, -apple-system, sans-serif"},[e("title",{id:"pb5-t2-title"},"Dual-Path Grounding Topology: Fabric IQ Structured Path vs. Foundry IQ Unstructured Path"),e("desc",{id:"pb5-t2-desc"},"Shows OneLake Shortcuts feeding Bronze-Silver-Gold; top lane routes curated Delta tables and Semantic Models through Fabric IQ and Fabric Data Agent to Foundry Agent Service; middle lane routes OneLake Files through Content Understanding and Shared Private Link to Azure AI Search Foundry IQ MCP; bottom lane shows Cosmos DB DiskANN Hybrid for operational memory and thread state."),e("defs",null,[e("marker",{id:"fiq-arr",markerWidth:"8",markerHeight:"8",refX:"7",refY:"4",orient:"auto"},[e("path",{d:"M0 0 L8 4 L0 8Z",fill:"#0f766e"})])]),e("rect",{x:"8",y:"20",width:"144",height:"156",rx:"6",fill:"#edf3fb",stroke:"#5b87b2","stroke-width":"1.4"}),e("text",{x:"16",y:"40","font-size":"9.0","font-weight":"700",fill:"#183e62"},"OneLake Foundation"),e("text",{x:"16",y:"58","font-size":"8.0",fill:"#334e68"},"• Zero-copy Shortcuts"),e("text",{x:"16",y:"72","font-size":"8.0",fill:"#334e68"},"• Delta Parquet Tables"),e("text",{x:"16",y:"86","font-size":"8.0",fill:"#334e68"},"• OneLake Files (Docs)"),e("text",{x:"16",y:"100","font-size":"8.0",fill:"#334e68"},"• Semantic Models"),e("text",{x:"16",y:"114","font-size":"8.0",fill:"#334e68"},"• OneLake Security"),e("text",{x:"16",y:"156","font-size":"7.7","font-weight":"700",fill:"#1d4ed8"},"[Single Source of Truth]"),e("path",{d:"M152 52 H186",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#fiq-arr)"}),e("path",{d:"M152 104 H186",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#fiq-arr)"}),e("path",{d:"M152 152 H186",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#fiq-arr)"}),e("rect",{x:"190",y:"20",width:"356",height:"48",rx:"6",fill:"#eaf7f5",stroke:"#0f766e","stroke-width":"1.5"}),e("text",{x:"200",y:"39","font-size":"8.8","font-weight":"700",fill:"#115e59"},"Path A · Structured / KPI Truth: Fabric IQ & Fabric Data Agent"),e("text",{x:"200",y:"55","font-size":"7.9",fill:"#334e68"},"Ontology + Semantic Models + SQL/DAX · Dedicated Interactive F-SKU · Identity Passthrough"),e("rect",{x:"190",y:"76",width:"356",height:"48",rx:"6",fill:"#edf3fb",stroke:"#0078d4","stroke-width":"1.5"}),e("text",{x:"200",y:"95","font-size":"8.8","font-weight":"700",fill:"#183e62"},"Path B · Unstructured Corpus: Content Understanding → AI Search (Foundry IQ)"),e("text",{x:"200",y:"111","font-size":"7.9",fill:"#334e68"},"Shared Private Link OneLake Indexer · Hybrid + Semantic Rerank · ACL + Purview Labels"),e("rect",{x:"190",y:"132",width:"356",height:"44",rx:"6",fill:"#f5f3ff",stroke:"#7c3aed","stroke-width":"1.5"}),e("text",{x:"200",y:"150","font-size":"8.8","font-weight":"700",fill:"#5b21b6"},"Path C · Operational Memory: Azure Cosmos DB (DiskANN + BM25 RRF)"),e("text",{x:"200",y:"165","font-size":"7.9",fill:"#334e68"},"Tenant-Partitioned Episodic Memory + Thread State + Real-Time Low-Latency Hybrid RAG"),e("path",{d:"M546 44 H582",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#fiq-arr)"}),e("path",{d:"M546 100 H582",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#fiq-arr)"}),e("path",{d:"M546 154 H582",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#fiq-arr)"}),e("rect",{x:"586",y:"20",width:"166",height:"156",rx:"6",fill:"#eaf4f5",stroke:"#0f766e","stroke-width":"1.5"}),e("text",{x:"594",y:"40","font-size":"9.0","font-weight":"700",fill:"#115e59"},"Foundry Agent Service"),e("text",{x:"594",y:"58","font-size":"8.0",fill:"#334e68"},"• Tool Router (Pos 1–3)"),e("text",{x:"594",y:"72","font-size":"8.0",fill:"#334e68"},"• fabric_iq tool (KPIs)"),e("text",{x:"594",y:"86","font-size":"8.0",fill:"#334e68"},"• knowledge_base_retrieve"),e("text",{x:"594",y:"100","font-size":"8.0",fill:"#334e68"},"• cosmos_hybrid_recall"),e("text",{x:"594",y:"114","font-size":"8.0",fill:"#334e68"},"• Outputs → Pos 6 tail"),e("text",{x:"594",y:"156","font-size":"7.7","font-weight":"700",fill:"#0f766e"},"[Zero Cross-Path Drift]"),e("text",{x:"10",y:"195","font-size":"8.3",fill:"#526c80"},"Every user question routes to the authoritative engine: Fabric IQ for aggregations/KPIs, AI Search for documents, Cosmos DB for live state.")])],-1)),t[3]||(t[3]=o('<hr><h2 id="_2-wiring-fabric-iq-fabric-data-agents-into-microsoft-foundry-m" tabindex="-1">2. Wiring Fabric IQ &amp; Fabric Data Agents Into Microsoft Foundry <code>[M]</code> <a class="header-anchor" href="#_2-wiring-fabric-iq-fabric-data-agents-into-microsoft-foundry-m" aria-label="Permalink to &quot;2. Wiring Fabric IQ &amp; Fabric Data Agents Into Microsoft Foundry `[M]`&quot;">​</a></h2><p><strong>Fabric IQ</strong> unifies business ontologies, Power BI semantic models, Lakehouses, Warehouses, and KQL Eventhouses into a governed semantic context layer over OneLake <span class="ev-badge ev-m">[M]</span>. Connecting a <strong>Microsoft Foundry</strong> agent to a published <strong>Fabric Data Agent / Fabric IQ</strong> tool provides three decisive advantages over ad-hoc text-to-SQL scripts:</p><ol><li><strong>Identity Passthrough &amp; Row/Object-Level Security (RLS/OLS):</strong> Foundry passes the calling user&#39;s Microsoft Entra identity (On-Behalf-Of) to Fabric so existing OneLake Security, Warehouse SQL permissions, and Power BI RLS rules filter every query natively—preventing service-account privilege escalation <span class="ev-badge ev-m">[M]</span>.</li><li><strong>Certified Metric Semantics:</strong> Queries execute against governed DAX measures and curated Gold schemas rather than guessing table joins across 400 raw staging tables <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>Cache-Safe Tool Schemas (<a href="/enterprise-azure-ai-hub/playbooks/prompt-caching/design/07-prefix-taxonomy">Playbook 01</a>):</strong> Registering <code>fabric_iq_query</code> alongside <code>knowledge_base_retrieve</code> in the canonically sorted <code>tools[]</code> array (<code>Pos 2</code>) keeps <code>Pos 1–3</code> static while appending returned tabular summaries strictly at <strong>Position 6</strong> <span class="ev-badge ev-arch">[Arch]</span>.</li></ol><h3 id="routing-decision-boundary-fabric-iq-vs-foundry-iq-ai-search" tabindex="-1">Routing Decision Boundary: Fabric IQ vs. Foundry IQ (AI Search) <a class="header-anchor" href="#routing-decision-boundary-fabric-iq-vs-foundry-iq-ai-search" aria-label="Permalink to &quot;Routing Decision Boundary: Fabric IQ vs. Foundry IQ (AI Search)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">User Intent Class</th><th style="text-align:left;">Correct Grounding Tool</th><th style="text-align:left;">Why Mis-Routing Fails</th></tr></thead><tbody><tr><td style="text-align:left;"><em>&quot;Compare Q3 net margin by region and flag accounts &gt;15% below forecast.&quot;</em></td><td style="text-align:left;"><strong>Fabric IQ / Fabric Data Agent</strong> (Semantic Model / Warehouse)</td><td style="text-align:left;">Vector chunks cannot compute exact SQL/DAX aggregations across live multi-million-row tables.</td></tr><tr><td style="text-align:left;"><em>&quot;Summarize indemnity exceptions in Master Services Agreements signed after 2024.&quot;</em></td><td style="text-align:left;"><strong>Azure AI Search (<code>Foundry IQ</code> MCP)</strong></td><td style="text-align:left;">Unstructured multi-page clauses require layout-aware chunking, hybrid BM25 + vector search, and semantic reranking.</td></tr><tr><td style="text-align:left;"><em>&quot;Recall the client&#39;s open action items from our last three sessions and match against uploaded draft.&quot;</em></td><td style="text-align:left;"><strong>Azure Cosmos DB (<code>DiskANN</code> + <code>RRF</code>)</strong> + <strong>AI Search</strong></td><td style="text-align:left;">High-churn, tenant-partitioned session/episodic memory requires single-digit millisecond operational writes and immediate vector consistency.</td></tr><tr><td style="text-align:left;"><em>&quot;Explain why Region West revenue dropped 12% and cite the relevant quarterly risk memo.&quot;</em></td><td style="text-align:left;"><strong>Dual-Path Composite:</strong> <code>fabric_iq</code> (exact variance) + <code>knowledge_base_retrieve</code> (risk memo prose)</td><td style="text-align:left;">Combines verified tabular math with citation-backed narrative evidence in one agent trace.</td></tr></tbody></table><hr><h2 id="_3-fabric-capacity-f-sku-isolation-cu-throttling-math-arch" tabindex="-1">3. Fabric Capacity (<code>F-SKU</code>) Isolation &amp; CU Throttling Math <code>[Arch]</code> <a class="header-anchor" href="#_3-fabric-capacity-f-sku-isolation-cu-throttling-math-arch" aria-label="Permalink to &quot;3. Fabric Capacity (`F-SKU`) Isolation &amp; CU Throttling Math `[Arch]`&quot;">​</a></h2><p>Microsoft Fabric bills compute in <strong>Capacity Units (CUs)</strong> with <strong>smoothing</strong> (spreading background Spark/ETL bursts over 24 hours and interactive queries over shorter windows) and <strong>bursting</strong> <span class="ev-badge ev-m">[M]</span>. When teams attach interactive <strong>Fabric IQ</strong> agents to the same F-SKU capacity running heavy nightly Spark/Dataflow refreshes, background smoothing debt triggers <strong>interactive delay or rejection throttling</strong> right during morning executive peak hours <span class="ev-badge ev-arch">[Arch]</span>.</p><h3 id="capacity-engineering-guardrails-gate-d3" tabindex="-1">Capacity Engineering Guardrails (<code>Gate D3</code>) <a class="header-anchor" href="#capacity-engineering-guardrails-gate-d3" aria-label="Permalink to &quot;Capacity Engineering Guardrails (`Gate D3`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Control</th><th style="text-align:left;">Anti-Pattern</th><th style="text-align:left;">Industrialized Production Standard</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Interactive vs. Batch Split</strong></td><td style="text-align:left;">Running Spark ingestion, Lakehouse table compaction, and live Foundry <code>Fabric IQ</code> queries on one shared <code>F64</code> capacity.</td><td style="text-align:left;">Place batch ETL/Medallion pipelines on a <strong>Batch F-SKU</strong> and bind read-only <strong>AI-Ready Gold</strong> shortcuts + Semantic Models + Fabric Data Agents to a dedicated <strong>Interactive AI-Serving F-SKU</strong> <span class="ev-badge ev-arch">[Arch]</span>.</td></tr><tr><td style="text-align:left;"><strong>Zero-Copy Cross-Capacity Access</strong></td><td style="text-align:left;">Copying Gold Delta tables across workspaces to separate compute billing.</td><td style="text-align:left;">Use <strong>OneLake Shortcuts</strong> across workspaces; compute charges land on the consuming capacity while storage remains single-copy in OneLake <span class="ev-badge ev-m">[M]</span>.</td></tr><tr><td style="text-align:left;"><strong>Headroom &amp; Surge Guardrail</strong></td><td style="text-align:left;">Operating the interactive AI-serving capacity above <code>85%</code> sustained CU utilization.</td><td style="text-align:left;">Keep steady-state interactive CU utilization <code>&lt;= 65%</code> (leaving <code>&gt;= 35%</code> burst headroom for concurrent multi-step agent tool fans) and alert on Fabric Capacity Metrics throttling events <span class="ev-badge ev-agree">[Agree]</span>.</td></tr><tr><td style="text-align:left;"><strong>Private Networking (<code>OneLake → AI Search</code>)</strong></td><td style="text-align:left;">Opening public workspace endpoints to allow Azure AI Search indexers to crawl OneLake Files.</td><td style="text-align:left;">Configure an <strong>Azure AI Search Shared Private Link</strong> to the Fabric workspace private endpoint so unstructured document indexing stays strictly on the Azure backbone <span class="ev-badge ev-m">[M]</span>.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Operational Check (Gate D2 &amp; D3)</p><p>Before promoting a Fabric IQ tool to production, verify that every Gold table and OneLake File folder carries immutable lineage metadata (<code>source_uri</code>, <code>lineage_sha256</code>, <code>medallion_tier=&quot;ai-gold&quot;</code>), and validate interactive CU headroom during a simulated peak agent burst (<code>data_readiness_gate.py</code> rule <code>DRG002</code>).</p></div>',12))])}const k=s(g,[["render",u]]);export{v as __pageData,k as default};
